    def longestCommonSubsequence(self, text1: str, text2: str) -> int:
        def lcs(ind1,ind2):
            prev=[0 for i in range(ind2+1)]
            curr=[0 for i in range(ind2+1)]

            for i in range(1,ind1+1):
                for j in range(1,ind2+1):
                    if text1[i-1]==text2[j-1]:
                        curr[j]=1+prev[j-1]

                    else:
                        curr[j]=max(prev[j],curr[j-1])
                prev=list(curr) # remember to use a new list for prev

            return prev[-1]


        ans=lcs(len(text1),len(text2))
        return ans

class Solution:
    def longestCommonSubsequence(self, text1: str, text2: str) -> int:
        if len(text1) < len(text2):
            return self.longestCommonSubsequence(text2, text1)

        dp = [[0 for _ in range(len(text2)+1)] for _ in range(2)]
        for i in range(1, len(text1)+1):
            for j in range(1, len(text2)+1):
                dp[i%2][j] = dp[(i-1)%2][j-1]+1 if text1[i-1] == text2[j-1] \
                             else max(dp[(i-1)%2][j], dp[i%2][j-1])
        return dp[len(text1)%2][len(text2)]

class Solution:
    def movesToMakeZigzag(self, nums):
        result = [0, 0]
        for i in range(len(nums)):
            left = nums[i-1] if i-1 >= 0 else float("inf")
            right = nums[i+1] if i+1 < len(nums) else float("inf")
            result[i%2] += max(nums[i] - min(left, right) + 1, 0)
        return min(result)

